/**
 * Generates a single-use signed token tied to a profile (and optional relationship) and emails it to the recipient.
 * @summary Create an invite token and send the claim email
 */
export const CreateInviteBody = zod.object({
  profileId: zod.string(),
  relationshipId: zod.string().nullish(),
  email: zod.string().email(),
});

/**
 * Public endpoint used by the claim landing page to render the invite
without requiring sign-in. A token that has already been claimed is
still resolvable (so the landing page can show a "this invite was
already accepted" state) and is signaled by `alreadyClaimed: true`
in the response body. Tokens that do not exist or have expired
return 404.

 * @summary Resolve an invite token to its preview metadata
 */
export const GetInviteParams = zod.object({
  token: zod.coerce.string(),
});

export const GetInviteResponse = zod.object({
  token: zod.string(),
  email: zod.string(),
  inviterName: zod.string().nullish(),
  profileName: zod.string(),
  relationshipId: zod.string().nullish(),
  relationshipReportId: zod.string().nullish(),
  expiresAt: zod.string(),
  alreadyClaimed: zod.boolean(),
});

/**
 * Requires Clerk authentication. Marks the token claimed, sets profile.claimed_by_user_id, and adds the user as a participant on the related relationship.
 * @summary Claim an invite as the signed-in user
 */
export const ClaimInviteParams = zod.object({
  token: zod.coerce.string(),
});

export const ClaimInviteResponse = zod.object({
  profileId: zod.string(),
  relationshipId: zod.string().nullish(),
  relationshipReportId: zod.string().nullish(),
  redirectTo: zod.string(),
});

/**
 * Converts a city/place name to latitude, longitude, and timezone
 * @summary Geocode a place name to coordinates
 */
export const GeocodePlaceQueryParams = zod.object({
  q: zod.coerce.string().describe("Place name to geocode"),
});

export const GeocodePlaceResponse = zod.object({
  results: zod.array(
    zod.object({
      name: zod.string().describe("Full display name (City, Region, Country)"),
      city: zod.string().optional().describe("City\/town\/village name"),
      region: zod.string().optional().describe("State or region name"),
      country: zod.string().optional().describe("Country name"),
      latitude: zod.number(),
      longitude: zod.number(),
      timezoneOffset: zod.number().describe("UTC offset in hours"),
      placeType: zod
        .string()
        .describe(
          "Nominatim place type (city, town, village, administrative, etc.)",
        ),
    }),
  ),
});
